ga0Q(){return"\u0627\u0644\u062d\u0627\u0644\u0627\u062a \u0627\u0644\u0623\u062e\u064a\u0631\u0629 \u0648\u0627\u0644\u0642\u0627\u062f\u0645\u0629"},
ga0N(){return"\u0644\u0627 \u062a\u0648\u062c\u062f \u062d\u0627\u0644\u0627\u062a \u0628\u0639\u062f."},
gVM(){return"\u0644\u0648\u062d\u0629 \u0627\u0644\u062d\u0627\u0644\u0627\u062a"},
