gNF(){return"\u0646\u0627\u0648\u06cc \u0628\u06d5\u06a9\u0627\u0631\u0647\u06ce\u0646\u06d5\u0631"},
gND(){return"\u0648\u0634\u06d5\u06cc \u0646\u0647\u06ce\u0646\u06cc"},
gNE(){return"\u0646\u0627\u0633\u0646\u0627\u0645\u06d5\u06cc \u062a\u06ce\u0631\u0645\u06cc\u0646\u0627\u06b5"},
gMG(){return"\u0646\u0627\u0633\u0646\u0627\u0645\u06d5\u06cc \u06a9\u0695\u06cc\u0627\u0631"},
gMH(){return"\u06a9\u06c6\u062f\u06cc \u0646\u0647\u06ce\u0646\u06cc \u06a9\u0695\u06cc\u0627\u0631"},
